      --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 16px rgba(0,0,0,0.06);
      --shadow-lg: 0 8px 32px rgba(0,0,0,0.08);
      --shadow-xl: 0 16px 48px rgba(0,0,0,0.1);
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --radius-full: 9999px;
      --font-display: 'Space Grotesk', system-ui, sans-serif;
      --font-body: 'Plus Jakarta Sans', system-ui, sans-serif;
      --font-mono: 'JetBrains Mono', monospace;
      --max-width: 1240px;
      --nav-height: 64px;
    }

    /* ===== Reset & Base ===== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    html {
      scroll-behavior: smooth;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    body {
      font-family: var(--font-body);
      font-size: 15px;
      line-height: 1.65;
      color: var(--text-primary);
      background: var(--bg-primary);
      overflow-x: hidden;
    }

    /* Noise texture overlay */
    body::before {
      content: '';
      position: fixed;
      inset: 0;
      background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
      opacity: 0.018;
      pointer-events: none;
      z-index: 9999;
    }

    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    ul { list-style: none; }

    .container {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ===== Animations ===== */
    @keyframes fadeSlideUp {
      from { opacity: 0; transform: translateY(16px); }
      to { opacity: 1; transform: translateY(0); }
    }

    @keyframes fadeIn {
      from { opacity: 0; }
      to { opacity: 1; }
    }

    @keyframes scaleIn {
      from { opacity: 0; transform: scale(0.96); }
      to { opacity: 1; transform: scale(1); }
    }

    @keyframes slideDown {
      from { opacity: 0; transform: translateY(-8px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .animate-in {
      animation: fadeSlideUp 0.5s ease-out both;
    }

    .reveal {
      opacity: 0;
      transform: translateY(16px);
      transition: opacity 0.5s ease, transform 0.5s ease;
    }

    .reveal.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* ===== Header ===== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(250, 250, 250, 0.85);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--border);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: var(--nav-height);
      gap: 32px;
    }

    .logo {
      font-family: var(--font-display);
      font-weight: 700;
      font-size: 18px;
      letter-spacing: -0.02em;
      color: var(--text-primary);
      display: flex;
      align-items: center;
      gap: 8px;
      flex-shrink: 0;
    }

    .logo-icon {
      width: 28px;
      height: 28px;
      background: var(--text-primary);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 14px;
      font-weight: 700;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 4px;
    }

    .nav-link {
      position: relative;
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 6px 12px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      border-radius: var(--radius-sm);
      transition: color 0.15s, background 0.15s;
      white-space: nowrap;
    }

    .nav-link:hover {
      color: var(--text-primary);
      background: var(--bg-secondary);
    }

    .nav-link svg {
      width: 14px;
      height: 14px;
      transition: transform 0.2s;
    }

    .nav-link.open svg {
      transform: rotate(180deg);
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-shrink: 0;
    }

    .btn-ask-ai {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 6px 14px;
      font-size: 13px;
      font-weight: 600;
      color: var(--accent);
      background: var(--accent-subtle);
      border-radius: var(--radius-full);
      transition: background 0.15s;
    }

    .btn-ask-ai:hover {
      background: var(--accent-subtle-hover);
    }

    .btn-login {
      padding: 6px 14px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      transition: color 0.15s;
    }

    .btn-login:hover { color: var(--text-primary); }

    .btn-signup {
      padding: 7px 18px;
      font-size: 14px;
      font-weight: 600;
      color: #fff;
      background: var(--text-primary);
      border-radius: var(--radius-full);
      transition: opacity 0.15s;
    }

    .btn-signup:hover { opacity: 0.85; }

    /* ===== Mega Menu ===== */
    .mega-menu-trigger { position: relative; }

    .mega-menu {
      position: absolute;
      top: calc(100% + 8px);
      left: 50%;
      transform: translateX(-50%);
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-xl);
      padding: 24px;
      min-width: 640px;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.2s, visibility 0.2s, transform 0.2s;
      transform: translateX(-50%) translateY(-4px);
      z-index: 200;
    }

    .mega-menu-trigger.open .mega-menu {
      opacity: 1;
      visibility: visible;
      transform: translateX(-50%) translateY(0);
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .mega-menu-col h4 {
      font-family: var(--font-display);
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--text-tertiary);
      margin-bottom: 12px;
    }

    .mega-menu-item {
      display: block;
      padding: 6px 0;
    }

    .mega-menu-item-title {
      font-size: 13.5px;
      font-weight: 600;
      color: var(--text-primary);
      line-height: 1.3;
    }

    .mega-menu-item-desc {
      font-size: 12px;
      color: var(--text-tertiary);
      line-height: 1.4;
      margin-top: 2px;
    }

    .mega-menu-item:hover .mega-menu-item-title {
      color: var(--accent);
    }

    /* Resources dropdown - simpler */
    .mega-menu.resources-menu {
      min-width: 420px;
    }

    .mega-menu.resources-menu .mega-menu-grid {
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .mega-menu-link {
      display: block;
      font-size: 13.5px;
      font-weight: 500;
      color: var(--text-secondary);
      padding: 4px 0;
      transition: color 0.15s;
    }

    .mega-menu-link:hover { color: var(--accent); }

    /* Mobile menu */
    .mobile-menu-btn {
      display: none;
      padding: 8px;
      color: var(--text-primary);
    }

    .mobile-menu-btn svg { width: 22px; height: 22px; }

    /* ===== Hero / Blog Header ===== */
    .blog-hero {
      position: relative;
      padding: 80px 0 48px;
      overflow: hidden;
    }

    .blog-hero::before {
      content: '';
      position: absolute;
      top: -200px;
      right: -200px;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(0, 114, 245, 0.06) 0%, transparent 70%);
      pointer-events: none;
    }

    .blog-hero::after {
      content: '';
      position: absolute;
      bottom: -100px;
      left: -100px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(0, 114, 245, 0.04) 0%, transparent 70%);
      pointer-events: none;
    }

    .blog-hero-content {
      position: relative;
      z-index: 1;
    }

    .blog-hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 5px 14px;
      font-size: 12px;
      font-weight: 600;
      color: var(--accent);
      background: var(--accent-subtle);
      border-radius: var(--radius-full);
      margin-bottom: 20px;
      animation: fadeSlideUp 0.5s ease-out 0.1s both;
    }

    .blog-hero-badge svg { width: 14px; height: 14px; }

    .blog-hero h1 {
      font-family: var(--font-display);
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 700;
      line-height: 1.08;
      letter-spacing: -0.035em;
      color: var(--text-primary);
      max-width: 640px;
      animation: fadeSlideUp 0.5s ease-out 0.2s both;
    }

    .blog-hero p {
      font-size: 17px;
      line-height: 1.6;
      color: var(--text-secondary);
      max-width: 520px;
      margin-top: 16px;
      animation: fadeSlideUp 0.5s ease-out 0.3s both;
    }

    /* ===== Category Filters ===== */
    .category-section {
      padding: 0 0 40px;
      border-bottom: 1px solid var(--border);
      animation: fadeSlideUp 0.5s ease-out 0.4s both;
    }

    .category-bar {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
    }

    .category-pill {
      padding: 7px 16px;
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      background: transparent;
      border: 1px solid var(--border);
      border-radius: var(--radius-full);
      transition: all 0.15s;
      white-space: nowrap;
    }

    .category-pill:hover {
      color: var(--text-primary);
      border-color: var(--border-hover);
      background: var(--bg-secondary);
    }

    .category-pill.active {
      color: #fff;
      background: var(--text-primary);
      border-color: var(--text-primary);
    }

    .search-input-wrap {
      position: relative;
      margin-left: auto;
    }

    .search-input-wrap svg {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      width: 16px;
      height: 16px;
      color: var(--text-tertiary);
      pointer-events: none;
    }

    .search-input {
      padding: 7px 14px 7px 36px;
      font-size: 13px;
      font-family: var(--font-body);
      color: var(--text-primary);
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-full);
      width: 200px;
      transition: border-color 0.15s, width 0.25s, box-shadow 0.15s;
      outline: none;
    }

    .search-input::placeholder { color: var(--text-tertiary); }

    .search-input:focus {
      border-color: var(--accent);
      width: 260px;
      box-shadow: 0 0 0 3px var(--accent-subtle);
    }

    /* ===== Featured Articles ===== */
    .featured-section {
      padding: 56px 0;
    }

    .section-label {
      font-family: var(--font-display);
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--accent);
      margin-bottom: 24px;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: 1.2fr 1fr;
      grid-template-rows: auto auto;
      gap: 20px;
    }

    .featured-card {
      position: relative;
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 28px;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s;
      overflow: hidden;
    }

    .featured-card:hover {
      border-color: var(--border-hover);
      box-shadow: var(--shadow-lg);
      transform: translateY(-2px);
    }

    .featured-card:first-child {
      grid-row: 1 / 3;
      padding: 36px;
      background: var(--text-primary);
      border-color: #2a2a2a;
    }

    .featured-card:first-child:hover {
      border-color: #3a3a3a;
    }

    .featured-card:first-child .featured-tag {
      background: rgba(0, 114, 245, 0.15);
      color: #5ba3ff;
      border-color: transparent;
    }

    .featured-card:first-child .featured-date {
      color: #888;
    }

    .featured-card:first-child .featured-title {
      color: #fafafa;
    }

    .featured-card:first-child .featured-excerpt {
      color: #999;
    }

    .featured-card:first-child .featured-author-name {
      color: #ccc;
    }

    .featured-card:first-child .featured-avatar {
      background: #333;
      color: #888;
    }

    /* Agentic stats overlay on first featured card */
    .agentic-stats {
      display: flex;
      gap: 24px;
      margin-top: 20px;
      padding-top: 20px;
      border-top: 1px solid #2a2a2a;
    }

    .agentic-stat {
      flex: 1;
    }

    .agentic-stat-value {
      font-family: var(--font-display);
      font-size: 22px;
      font-weight: 700;
      color: #5ba3ff;
      line-height: 1.2;
    }

    .agentic-stat-label {
      font-size: 12px;
      color: #777;
      line-height: 1.4;
      margin-top: 4px;
    }

    .featured-tag {
      display: inline-flex;
      padding: 3px 10px;
      font-size: 11px;
      font-weight: 600;
      color: var(--accent);
      background: var(--accent-subtle);
      border: 1px solid transparent;
      border-radius: var(--radius-full);
      margin-bottom: 14px;
      width: fit-content;
    }

    .featured-date {
      font-size: 13px;
      color: var(--text-tertiary);
      margin-bottom: 8px;
    }

    .featured-title {
      font-family: var(--font-display);
      font-size: 22px;
      font-weight: 600;
      line-height: 1.25;
      letter-spacing: -0.02em;
      color: var(--text-primary);
      margin-bottom: 10px;
    }

    .featured-card:first-child .featured-title {
      font-size: 30px;
    }

    .featured-excerpt {
      font-size: 14px;
      line-height: 1.6;
      color: var(--text-secondary);
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .featured-card:first-child .featured-excerpt {
      -webkit-line-clamp: 4;
    }

    .featured-author {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: auto;
      padding-top: 18px;
    }

    .featured-avatar {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--bg-secondary);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
      font-weight: 600;
      color: var(--text-tertiary);
      flex-shrink: 0;
    }

    .featured-author-name {
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
    }

    /* ===== Latest News Grid ===== */
    .latest-section {
      padding: 48px 0;
    }

    .latest-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 28px;
    }

    .latest-header h2 {
      font-family: var(--font-display);
      font-size: 24px;
      font-weight: 600;
      letter-spacing: -0.02em;
    }

    .posts-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .post-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 24px;
      display: flex;
      flex-direction: column;
      transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s;
    }

    .post-card:hover {
      border-color: var(--border-hover);
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .post-tag {
      display: inline-flex;
      padding: 2px 10px;
      font-size: 11px;
      font-weight: 600;
      color: var(--accent);
      background: var(--accent-subtle);
      border-radius: var(--radius-full);
      margin-bottom: 14px;
      width: fit-content;
    }

    .post-meta {
      font-size: 12.5px;
      color: var(--text-tertiary);
      margin-bottom: 8px;
    }

    .post-title {
      font-family: var(--font-display);
      font-size: 16px;
      font-weight: 600;
      line-height: 1.3;
      letter-spacing: -0.01em;
      color: var(--text-primary);
      margin-bottom: 8px;
    }

    .post-title:hover { color: var(--accent); }

    .post-excerpt {
      font-size: 13.5px;
      line-height: 1.55;
      color: var(--text-secondary);
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
      flex: 1;
    }

    .post-footer {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 16px;
      padding-top: 14px;
      border-top: 1px solid var(--border);
    }

    .post-avatar {
      width: 24px;
      height: 24px;
      border-radius: 50%;
      background: var(--bg-secondary);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 9px;
      font-weight: 600;
      color: var(--text-tertiary);
      flex-shrink: 0;
    }

    .post-author {
      font-size: 12.5px;
      color: var(--text-secondary);
      font-weight: 500;
    }

    /* No results */
    .no-results {
      grid-column: 1 / -1;
      text-align: center;
      padding: 64px 24px;
    }

    .no-results-icon {
      width: 48px;
      height: 48px;
      color: var(--text-tertiary);
      margin: 0 auto 16px;
      opacity: 0.5;
    }

    .no-results h3 {
      font-family: var(--font-display);
      font-size: 18px;
      font-weight: 600;
      margin-bottom: 8px;
    }

    .no-results p {
      font-size: 14px;
      color: var(--text-tertiary);
    }

    /* Show more */
    .show-more-wrap {
      text-align: center;
      padding-top: 36px;
    }

    .btn-show-more {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 11px 28px;
      font-size: 14px;
      font-weight: 600;
      color: var(--text-primary);
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-full);
      transition: all 0.15s;
    }

    .btn-show-more:hover {
      border-color: var(--border-hover);
      box-shadow: var(--shadow-sm);
    }

    .btn-show-more svg {
      width: 16px;
      height: 16px;
    }

    /* ===== CTA Banner ===== */
    .cta-section {
      padding: 56px 0;
    }

    .cta-banner {
      position: relative;
      background: var(--text-primary);
      border-radius: var(--radius-lg);
      padding: 56px 48px;
      overflow: hidden;
    }

    .cta-banner::before {
      content: '';
      position: absolute;
      top: -100px;
      right: -100px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(0, 114, 245, 0.2) 0%, transparent 70%);
      pointer-events: none;
    }

    .cta-banner::after {
      content: '';
      position: absolute;
      bottom: -60px;
      left: 40%;
      width: 300px;
      height: 300px;
      background: radial-gradient(circle, rgba(0, 114, 245, 0.1) 0%, transparent 70%);
      pointer-events: none;
    }

    .cta-content {
      position: relative;
      z-index: 1;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 40px;
    }

    .cta-text h2 {
      font-family: var(--font-display);
      font-size: clamp(22px, 3vw, 30px);
      font-weight: 600;
      line-height: 1.2;
      letter-spacing: -0.02em;
      color: #fafafa;
      max-width: 520px;
    }

    .cta-text h2 strong {
      color: #5ba3ff;
    }

    .cta-text p {
      font-size: 14px;
      color: #888;
      margin-top: 10px;
      max-width: 400px;
    }

    .cta-buttons {
      display: flex;
      gap: 12px;
      flex-shrink: 0;
    }

    .btn-primary-cta {
      padding: 11px 28px;
      font-size: 14px;
      font-weight: 600;
      color: var(--text-primary);
      background: #fff;
      border-radius: var(--radius-full);
      transition: opacity 0.15s;
    }

    .btn-primary-cta:hover { opacity: 0.9; }

    .btn-secondary-cta {
      padding: 11px 28px;
      font-size: 14px;
      font-weight: 600;
      color: #ccc;
      background: transparent;
      border: 1px solid #333;
      border-radius: var(--radius-full);
      transition: all 0.15s;
    }

    .btn-secondary-cta:hover {
      color: #fff;
      border-color: #555;
    }

    /* Enterprise block */
    .enterprise-block {
      position: relative;
      z-index: 1;
      margin-top: 32px;
      padding-top: 28px;
      border-top: 1px solid #2a2a2a;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }

    .enterprise-text {
      font-size: 14px;
      color: #888;
    }

    .btn-enterprise {
      padding: 9px 22px;
      font-size: 13px;
      font-weight: 600;
      color: #5ba3ff;
      background: rgba(0, 114, 245, 0.1);
      border: 1px solid rgba(0, 114, 245, 0.2);
      border-radius: var(--radius-full);
