    /* ===== Footer ===== */
    .footer {
      background: var(--bg-secondary);
      border-top: 1px solid var(--border);
      padding: 56px 0 32px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 32px;
    }

