      display: block;
      font-size: 13px;
      color: var(--text-secondary);
      padding: 3px 0;
      transition: color 0.15s;
    }

    .footer-col a:hover { color: var(--accent); }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-top: 40px;
      padding-top: 24px;
      border-top: 1px solid var(--border);
    }

    .footer-status {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 12px;
      color: var(--text-tertiary);
    }

    .footer-status-dot {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #22c55e;
    }

    .footer-copy {
      font-size: 12px;
      color: var(--text-tertiary);
    }

    .footer-social {
      display: flex;
      gap: 16px;
    }

    .footer-social a {
      color: var(--text-tertiary);
      transition: color 0.15s;
    }

    .footer-social a:hover { color: var(--text-primary); }

    .footer-social svg { width: 18px; height: 18px; }

    /* ===== Mobile Overlay ===== */
    .mobile-overlay {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.4);
      z-index: 150;
    }

    .mobile-nav-panel {
      display: none;
      position: fixed;
      top: 0;
      right: 0;
      width: 300px;
      height: 100%;
      background: var(--bg-card);
      z-index: 200;
      padding: 24px;
      overflow-y: auto;
      transform: translateX(100%);
      transition: transform 0.3s ease;
    }

    .mobile-nav-panel.open {
      transform: translateX(0);
    }

    .mobile-nav-close {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      margin-bottom: 24px;
    }

    .mobile-nav-close button {
      padding: 8px;
      color: var(--text-primary);
    }

    .mobile-nav-link {
      display: block;
      padding: 12px 0;
      font-size: 15px;
      font-weight: 500;
      color: var(--text-primary);
      border-bottom: 1px solid var(--border);
    }

    .mobile-nav-actions {
      margin-top: 24px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    /* ===== Responsive ===== */
    @media (max-width: 1024px) {
      .featured-grid {
        grid-template-columns: 1fr 1fr;
      }

      .featured-card:first-child {
        grid-row: auto;
      }

      .footer-grid {
        grid-template-columns: repeat(3, 1fr);
      }
    }

    @media (max-width: 768px) {
      .nav-links, .nav-actions { display: none; }
      .mobile-menu-btn { display: flex; }

      .mobile-overlay.active { display: block; }
      .mobile-nav-panel.active { display: block; transform: translateX(0); }

      .blog-hero { padding: 48px 0 32px; }

      .category-bar {
        overflow-x: auto;
        flex-wrap: nowrap;
        -webkit-overflow-scrolling: touch;
        padding-bottom: 8px;
        scrollbar-width: none;
      }

      .category-bar::-webkit-scrollbar { display: none; }
      .search-input-wrap { margin-left: 0; flex-shrink: 0; }
      .search-input { width: 140px; }
      .search-input:focus { width: 180px; }

      .featured-grid {
        grid-template-columns: 1fr;
      }

      .featured-card:first-child .featured-title {
        font-size: 24px;
      }

      .agentic-stats {
        flex-direction: column;
        gap: 12px;
      }

      .posts-grid {
        grid-template-columns: 1fr;
      }

      .cta-content {
        flex-direction: column;
        text-align: center;
      }

      .cta-text p { margin: 10px auto 0; }
      .cta-buttons { justify-content: center; }

      .enterprise-block {
        flex-direction: column;
        text-align: center;
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 24px;
      }

      .footer-bottom {
        flex-direction: column;
        gap: 12px;
        text-align: center;
      }
    }

    @media (max-width: 480px) {
